import { system, world } from "@minecraft/server";
import { ActionFormData, FormCancelationReason, uiManager } from "@minecraft/server-ui";
import { DURATION, IDX, PROGRESS_STEPS, SEGMENTS, TEX, THUMB_POSITIONS, TITLE } from "./bm_layout.js";
import {
    applySettings,
    canEditSetting,
    getSettingsForTab,
    getSettingValue,
    settingLabelTexture,
    settingValueTexture
} from "./bm_settings.js";
import { ACHIEVEMENTS, PLACEHOLDER_ICON, getAchievementState, getAchievementSummary } from "./bm_achievements.js";

// The look lives in RP/ui/black_mesa_menu.json (generated by tools/bm_menu/generate_ui.mjs).
// Each screen sends a fixed list of form buttons; bm_layout.js says which index is which control.

// SECTION: Constants
const OPEN_MENU_TAG = "brr_open_black_mesa_menu";
const OPEN_MENU_EVENT = "brr:open_black_mesa_menu";
const SAVE_PROPERTY = "brr_bm_save";
const LEGACY_HAS_SAVE_PROPERTY = "brr_bm_has_save";
const LEGACY_CHAPTER_PROPERTY = "brr_bm_selected_chapter";

// Run when a chapter starts (behind its loading screen) / when RESUME is pressed, if the map defines them.
const CHAPTER_FUNCTION = (number) => `black_mesa/chapters/ch${pad(number)}`;
const RESUME_FUNCTION = "black_mesa/resume";

const CHAPTERS = [
    "BLACK MESA INBOUND", "ANOMALOUS MATERIALS", "UNFORESEEN CONSEQUENCES", "OFFICE COMPLEX",
    "\"WE'VE GOT HOSTILES\"", "BLAST PIT", "POWER UP", "ON A RAIL",
    "APPREHENSION", "RESIDUE PROCESSING", "QUESTIONABLE ETHICS", "SURFACE TENSION",
    "\"FORGET ABOUT FREEMAN!\"", "LAMBDA CORE", "XEN", "GONARCH'S LAIR",
    "INTERLOPER", "NIHILANTH", "END GAME", "CREDITS"
];
// Chapters that exist in the map (1-based). Others show a black thumbnail and can't be started.
// Add a chapter here once it's built, along with RP/textures/ui/black_mesa/menu/chapters/chNN.png.
const PLAYABLE_CHAPTERS = new Set([1]);
const isPlayable = (chapter) => PLAYABLE_CHAPTERS.has(chapter + 1);

const CARDS_PER_PAGE = 4;
const PAGE_COUNT = Math.ceil(CHAPTERS.length / CARDS_PER_PAGE);
const ACH_COLUMNS = 2;
const ACH_VISIBLE_ROWS = IDX.achievements.cards / ACH_COLUMNS;

const BLANK = `${TEX}/shapes/blank`;
const BUSY_RETRY_TICKS = 4;
const BUSY_RETRY_LIMIT = 50;

const DAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

// SECTION: Helpers
function pad(n) {
    return `${n}`.padStart(2, "0");
}

const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
const chapterTexture = (kind, chapter) => `${TEX}/text/${kind}_${pad(chapter + 1)}`;

function formatTimestamp(ms) {
    const d = new Date(ms);
    return `${DAYS[d.getDay()]}, ${MONTHS[d.getMonth()]} ${d.getDate()} ${d.getFullYear()} `
        + `${d.getHours()}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

function runFunction(player, name) {
    try {
        player.runCommand(`function ${name}`);
    } catch {
        // The map hasn't defined this hook.
    }
}

// SECTION: Session State
const sessions = new Map();

function session(player) {
    let s = sessions.get(player.id);
    if (!s) {
        s = { booted: false, page: undefined, selected: 0, optionsTab: "GAME", draft: {}, selectedRow: 0, achScroll: 0, screenToken: 0 };
        sessions.set(player.id, s);
    }
    return s;
}

world.afterEvents.playerLeave.subscribe(({ playerId }) => sessions.delete(playerId));

// SECTION: Save Data
function getSave(player) {
    try {
        const raw = player.getDynamicProperty(SAVE_PROPERTY);
        if (typeof raw === "string") {
            const save = JSON.parse(raw);
            if (Number.isInteger(save?.chapter) && save.chapter >= 0 && save.chapter < CHAPTERS.length) return save;
        }

        // Carry over saves made by the previous version of the menu.
        if (player.getDynamicProperty(LEGACY_HAS_SAVE_PROPERTY) === true) {
            const chapter = clamp(Number.parseInt(`${player.getDynamicProperty(LEGACY_CHAPTER_PROPERTY) ?? 0}`, 10) || 0, 0, CHAPTERS.length - 1);
            player.setDynamicProperty(LEGACY_HAS_SAVE_PROPERTY, undefined);
            player.setDynamicProperty(LEGACY_CHAPTER_PROPERTY, undefined);
            return setSave(player, chapter);
        }
    } catch { }
    return undefined;
}

function setSave(player, chapter) {
    const save = { chapter, time: Date.now() };
    try {
        player.setDynamicProperty(SAVE_PROPERTY, JSON.stringify(save));
    } catch { }
    return save;
}

// SECTION: Form Presentation
function blankButtons(count) {
    return Array.from({ length: count }, () => ({ text: "", icon: BLANK }));
}

function withTabs(buttons) {
    ["CAMPAIGN", "MULTIPLAYER", "OPTIONS", "ACHIEVEMENTS"].forEach((label, i) => { buttons[IDX.tabs[i]] = { text: label }; });
    return buttons;
}

function present(player, title, buttons, onSelect, onClose, attempt = 0) {
    const form = new ActionFormData().title(title).body("");
    for (const button of buttons) form.button(button.text ?? "", button.icon);

    form.show(player).then((response) => {
        if (!player.isValid) return;
        if (response.canceled) {
            if (response.cancelationReason === FormCancelationReason.UserBusy && attempt < BUSY_RETRY_LIMIT) {
                system.runTimeout(() => {
                    if (player.isValid) present(player, title, buttons, onSelect, onClose, attempt + 1);
                }, BUSY_RETRY_TICKS);
                return;
            }
            onClose?.();
            return;
        }
        onSelect?.(response.selection);
    }).catch(() => { });
}

// Full-screen non-interactive screen that closes itself after `seconds` (or early on ESC), then runs `next`.
function presentTimed(player, title, buttons, seconds, next) {
    const s = session(player);
    const token = ++s.screenToken;
    const advance = () => {
        if (s.screenToken !== token) return;
        s.screenToken++;
        next?.();
    };

    present(player, title, buttons, advance, advance);
    system.runTimeout(() => {
        if (s.screenToken === token && player.isValid) uiManager.closeAllForms(player);
    }, Math.round(seconds * 20));
}

// Top tab row. Returns true if the selection was a tab.
function handleTab(player, selection, reshow, leavingOptions = false) {
    const tab = IDX.tabs.indexOf(selection);
    if (tab < 0) return false;

    if (leavingOptions && tab !== 2) session(player).draft = {};
    if (tab === 0) showCampaign(player);
    else if (tab === 2) showOptions(player);
    else if (tab === 3) showAchievements(player);
    else reshow();
    return true;
}

// SECTION: Boot and Loading
function openMenu(player) {
    const s = session(player);
    if (s.booted) {
        showHub(player);
        return;
    }

    s.booted = true;
    presentTimed(player, TITLE.splash, [{ text: "" }], DURATION.splash, () =>
        presentTimed(player, TITLE.bootLoad, [{ text: "" }], DURATION.bootLoad, () => showHub(player)));
}

function startChapter(player, chapter) {
    if (!isPlayable(chapter)) return;
    const s = session(player);
    s.selected = chapter;
    s.page = Math.floor(chapter / CARDS_PER_PAGE);
    setSave(player, chapter);

    presentTimed(player, TITLE.chapterLoad, [{ text: CHAPTERS[chapter], icon: chapterTexture("load_title", chapter) }], DURATION.chapterLoad);
    runFunction(player, CHAPTER_FUNCTION(chapter + 1));
}

// SECTION: Hub
function showHub(player) {
    const save = getSave(player);
    const buttons = withTabs(blankButtons(IDX.hub.count));
    buttons[IDX.hub.primary] = { text: save ? "RESUME" : "START GAME" };
    if (save) {
        buttons[IDX.hub.chapter] = { text: CHAPTERS[save.chapter], icon: chapterTexture("hub_title", save.chapter) };
        buttons[IDX.hub.time] = { text: formatTimestamp(save.time) };
    }

    present(player, save ? TITLE.hubSave : TITLE.hubNew, buttons, (selection) => {
        if (handleTab(player, selection, () => showHub(player))) return;
        if (selection === IDX.hub.primary) {
            if (save) runFunction(player, RESUME_FUNCTION);
            else startChapter(player, 0);
            return;
        }
        showHub(player);
    });
}

// SECTION: Campaign
function showCampaign(player) {
    const s = session(player);
    const save = getSave(player);
    if (s.page === undefined) {
        s.selected = save?.chapter ?? 0;
        s.page = Math.floor(s.selected / CARDS_PER_PAGE);
    }

    const c = IDX.campaign;
    const first = s.page * CARDS_PER_PAGE;
    const slot = s.selected - first;
    let title = TITLE.campaign;
    if (slot >= 0 && slot < CARDS_PER_PAGE) title += `|S${slot}|`;
    if (isPlayable(s.selected)) title += "|A|";
    if (s.page > 0) title += "|L|";
    if (s.page < PAGE_COUNT - 1) title += "|R|";
    if (save) title += "|G|";

    const buttons = withTabs(blankButtons(c.count));
    buttons[IDX.back] = { text: "BACK" };
    buttons[c.newGame] = { text: "NEW GAME" };
    buttons[c.loadGame] = { text: "LOAD GAME" };
    buttons[c.saveGame] = { text: "SAVE GAME" };
    buttons[c.prev] = { text: "PREV" };
    buttons[c.next] = { text: "NEXT" };
    buttons[c.start] = { text: "START GAME" };
    for (let k = 0; k < CARDS_PER_PAGE; k++) {
        const chapter = first + k;
        if (chapter >= CHAPTERS.length) continue;
        buttons[c.cardHit + k] = {
            text: CHAPTERS[chapter],
            icon: isPlayable(chapter) ? `${TEX}/chapters/ch${pad(chapter + 1)}` : `${TEX}/shapes/black`
        };
        buttons[c.cardTitle + k] = { text: "", icon: chapterTexture("card_text", chapter) };
    }

    present(player, title, buttons, (selection) => {
        if (handleTab(player, selection, () => showCampaign(player))) return;

        if (selection === IDX.back) return showHub(player);
        if (selection === c.saveGame && save) setSave(player, save.chapter);
        if (selection === c.prev) s.page = Math.max(0, s.page - 1);
        if (selection === c.next) s.page = Math.min(PAGE_COUNT - 1, s.page + 1);
        if (selection === c.start && isPlayable(s.selected)) return startChapter(player, s.selected);
        if (selection >= c.cardHit && selection < c.cardHit + CARDS_PER_PAGE) {
            s.selected = Math.min(CHAPTERS.length - 1, first + selection - c.cardHit);
        }
        showCampaign(player);
    });
}

// SECTION: Options
function showOptions(player, tab) {
    const s = session(player);
    if (tab) s.optionsTab = tab;

    const o = IDX.options;
    const settings = getSettingsForTab(s.optionsTab).slice(0, o.rows);
    if (s.selectedRow >= settings.length) s.selectedRow = 0;

    let title = TITLE.optionsTab[s.optionsTab];
    const buttons = withTabs(blankButtons(o.count));
    buttons[IDX.back] = { text: "BACK" };
    ["GAME", "VIDEO", "AUDIO"].forEach((name, i) => { buttons[o.subtabs + i] = { text: name }; });
    buttons[o.discard] = { text: "DISCARD CHANGES" };
    buttons[o.apply] = { text: "APPLY CHANGES" };

    settings.forEach((setting, r) => {
        const base = o.rowBase + o.rowStride * r;
        const editable = canEditSetting(player, setting);
        const selected = r === s.selectedRow;
        const value = s.draft[setting.id] ?? getSettingValue(player, setting.id);
        const index = Math.max(0, setting.values.indexOf(value));
        const state = !editable ? "lock" : selected ? "sel" : "";
        const last = setting.values.length - 1;

        title += setting.kind === "slider" ? `|r${r}s|` : `|r${r}c|`;
        if (selected) title += `|r${r}x|`;

        let tokens = editable ? "{on}" : "";
        if (setting.kind === "slider") {
            for (let i = 0; i < index; i++) tokens += `{f${i}}`;
            tokens += `{k${index}}`;
        } else {
            tokens += `{n${clamp(setting.values.length, SEGMENTS.min, SEGMENTS.max)}}{s${index}}`;
            if (editable && index > 0) tokens += "{la}";
            if (editable && index < last) tokens += "{ra}";
        }

        buttons[base] = { text: setting.id, icon: settingLabelTexture(setting, state) };
        buttons[base + 1] = { text: `${value}`, icon: settingValueTexture(setting, value, state) };
        buttons[base + 2] = { text: editable ? "{on}" : "" };
        buttons[base + 3] = { text: tokens };
    });

    present(player, title, buttons, (selection) => {
        if (handleTab(player, selection, () => showOptions(player), true)) return;

        if (selection === IDX.back) {
            s.draft = {};
            return showHub(player);
        }
        if (selection >= o.subtabs && selection < o.subtabs + 3) {
            s.selectedRow = 0;
            return showOptions(player, ["GAME", "VIDEO", "AUDIO"][selection - o.subtabs]);
        }
        if (selection === o.discard) s.draft = {};
        if (selection === o.apply) {
            applySettings(player, s.draft);
            s.draft = {};
        }

        const offset = selection - o.rowBase;
        const row = Math.floor(offset / o.rowStride);
        const part = offset % o.rowStride;
        const setting = settings[row];
        if (offset >= 0 && setting && (part === 2 || part === 3) && canEditSetting(player, setting)) {
            s.selectedRow = row;
            const current = s.draft[setting.id] ?? getSettingValue(player, setting.id);
            const index = clamp(setting.values.indexOf(current) + (part === 3 ? 1 : -1), 0, setting.values.length - 1);
            const next = setting.values[index];
            if (next === getSettingValue(player, setting.id)) delete s.draft[setting.id];
            else s.draft[setting.id] = next;
        }
        showOptions(player);
    });
}

// SECTION: Achievements
function showAchievements(player) {
    const s = session(player);
    const a = IDX.achievements;
    const totalRows = Math.ceil(ACHIEVEMENTS.length / ACH_COLUMNS);
    const maxScroll = Math.max(0, totalRows - ACH_VISIBLE_ROWS);
    s.achScroll = clamp(s.achScroll, 0, maxScroll);

    const { done, total } = getAchievementSummary(player);
    const filled = total > 0 ? Math.round((done / total) * PROGRESS_STEPS) : 0;
    let bar = "";
    for (let i = 0; i < filled; i++) bar += `{p${i}}`;
    if (maxScroll > 0) bar += `{sb}{t${Math.round((s.achScroll / maxScroll) * (THUMB_POSITIONS - 1))}}`;

    const buttons = withTabs(blankButtons(a.count));
    buttons[IDX.back] = { text: "BACK" };
    buttons[a.up] = { text: s.achScroll > 0 ? "{on}" : "" };
    buttons[a.down] = { text: s.achScroll < maxScroll ? "{on}" : "" };
    buttons[a.done] = { text: `${done}` };
    buttons[a.total] = { text: `/ ${total}` };
    buttons[a.bar] = { text: bar };

    for (let k = 0; k < a.cards; k++) {
        const achievement = ACHIEVEMENTS[s.achScroll * ACH_COLUMNS + k];
        if (!achievement) continue;

        const { progress, goal, unlocked } = getAchievementState(player, achievement);
        const token = unlocked ? "{U}" : "{L}";
        const base = a.cardBase + a.cardStride * k;
        buttons[base] = { text: token, icon: achievement.icon ?? PLACEHOLDER_ICON };
        buttons[base + 1] = { text: `${achievement.name}${token}` };
        buttons[base + 2] = { text: `${achievement.description}${token}` };
        buttons[base + 3] = { text: goal > 1 ? `${progress} / ${goal}` : "" };
    }

    present(player, TITLE.achievements, buttons, (selection) => {
        if (handleTab(player, selection, () => showAchievements(player))) return;
        if (selection === IDX.back) return showHub(player);
        if (selection === a.up) s.achScroll--;
        if (selection === a.down) s.achScroll++;
        showAchievements(player);
    });
}

// SECTION: Entry Points
// /scriptevent brr:open_black_mesa_menu (run as the player), or the legacy brr_open_black_mesa_menu tag.
system.afterEvents.scriptEventReceive.subscribe((event) => {
    if (event.id !== OPEN_MENU_EVENT || event.sourceEntity?.typeId !== "minecraft:player") return;
    const player = event.sourceEntity;
    // Opening a form in the same tick as a chat command can report UserBusy; present() retries.
    system.run(() => {
        if (player.isValid) openMenu(player);
    });
});

export function processBlackMesaMenuRequests() {
    for (const player of world.getPlayers({ tags: [OPEN_MENU_TAG] })) {
        try {
            player.removeTag(OPEN_MENU_TAG);
        } catch { }
        openMenu(player);
    }
}

export function openBlackMesaMenuForPlayer(player) {
    if (player?.isValid) openMenu(player);
}
